"""Quarter_Notes_UI lazy SEC/MD&A source-harvest row factories.

This module owns filing/document-cache adapters and source-harvest row factories
only. Candidate-map mutation, audit lifecycle, and workbook rendering remain with
the caller so provenance and visible output retain their original order.
"""
from __future__ import annotations

import re
from dataclasses import dataclass
from datetime import date
